INSERT INTO `word_translations` (`word_id`, `ur_meaning`, `en_meaning`, `pashto_text`, `bn_meaning`, `approved_by`, `approved_at`) VALUES
(0, 'ur_meaning', 'en_meaning', 'pashto_text', '', 1, '2025-08-24 09:07:18'),
(1, 'ساتھ نام', 'In (the) name', 'نوم سره', 'Mashallah', 1, '2025-08-24 13:02:18'),
(2, 'اللہ کے', '(of) Allah', 'د الله تعالی', '', 1, '2025-08-24 09:07:18'),
(3, 'جو بے حد مہربان ہے', 'the Most Gracious', 'څوک چې ډېر مهربانه وي', '', 1, '2025-08-24 09:07:18'),
(4, 'بار بار رحم فرمانے والا ہے', 'the Most Merciful', 'هغه تل رحم کوونکی دی', '', 1, '2025-08-24 09:07:18'),
(5, 'سب تعریف', 'All praises and thanks', 'ټول ستاینه', '', 1, '2025-08-24 09:07:18'),
(6, 'اللہ کے لیے ہے', '(be) to Allah', 'د الله لپاره دی', '', 1, '2025-08-24 09:07:18'),
(7, 'جو رب ہے', 'the Lord', 'رب څوک دی', '', 1, '2025-08-24 09:07:18'),
(8, 'تمام جہانوں کا', 'of the universe', 'د ټولو نړیو څخه', '', 1, '2025-08-24 09:07:18'),
(9, 'جو بہت مہربان', 'The Most Gracious', 'کوم چې ډیر مهربان دی', '', 1, '2025-08-24 09:07:18'),
(10, 'بار بار رحم فرمانے والا ہے', 'the Most Merciful', 'هغه تل رحم کوونکی دی', '', 1, '2025-08-24 09:07:18'),
(11, 'مالک ہے', '(The) Master', 'مالک دی', '', 1, '2025-08-24 09:07:18'),
(12, 'دن کا', '(of the) Day', 'د ورځې', '', 1, '2025-08-24 09:07:18'),
(13, 'بدلے کے', '(of the) Judgment', 'په بدل کې', '', 1, '2025-08-24 09:07:18'),
(14, 'صرف تیری', 'You Alone', 'یوازې ستاسو', '', 1, '2025-08-24 09:07:18'),
(15, 'ہم عبادت کرتے ہیں', 'we worship', 'موږ عبادت کوو', '', 1, '2025-08-24 09:07:18'),
(16, 'اور صرف تجھ سے', 'and You Alone', 'او یوازې له تاسو څخه', '', 1, '2025-08-24 09:07:18'),
(17, 'ہم مدد چاہتے ہیں', 'we ask for help', 'موږ مرسته غواړو', '', 1, '2025-08-24 09:07:19'),
(18, 'دکھا ہم کو', 'Guide us', 'موږ ته وښایه', '', 1, '2025-08-24 09:07:19'),
(19, 'راستہ', '(to) the path', 'لاره', '', 1, '2025-08-24 09:07:19'),
(20, 'سیدھا', 'the straight', 'مستقیم', '', 1, '2025-08-24 09:07:19'),
(21, 'راستہ', '(The) path', 'لاره', '', 1, '2025-08-24 09:07:19'),
(22, 'ان لوگوں کا', '(of) those', 'د دې خلکو څخه', '', 1, '2025-08-24 09:07:19'),
(23, 'انعام کیا تو نے', 'You have bestowed (Your) Favors', 'تاسو څه انعام ورکړ؟', '', 1, '2025-08-24 09:07:19'),
(24, 'اوپر ان کے', 'on them', 'د دوی پورته', '', 1, '2025-08-24 09:07:19'),
(25, 'نہ ان (لوگوں) کا', 'not (of)', 'نه د دوی (خلک).', '', 1, '2025-08-24 09:07:19'),
(26, 'غضب کیا گیا', 'those who earned (Your) wrath', 'هغه په ​​غوسه و', '', 1, '2025-08-24 09:07:19'),
(27, 'اوپر ان کے', 'on themselves', 'د دوی پورته', '', 1, '2025-08-24 09:07:19'),
(28, 'اور نہ', 'and not', 'او نه', '', 1, '2025-08-24 09:07:19'),
(29, 'ان (لوگوں) کا جو گمراہ ہیں / گم کردہ راہ ہیں', '(of) those who go astray', 'له هغو (خلکو) څخه چې ګمراه شوي / ورک شوي دي', '', 1, '2025-08-24 09:07:19'),
(30, 'الف ۔ لام ۔ میم', 'Alif Laam Meem', 'الف لام. میم', '', 1, '2025-08-24 09:07:19'),
(31, 'وہ / یہ', 'That', 'هغه / دا', '', 1, '2025-08-24 09:07:19'),
(32, 'کتاب ہے', '(is) the book', 'یو کتاب دی', '', 1, '2025-08-24 09:07:19'),
(33, 'نہیں', 'no', 'نه', '', 1, '2025-08-24 09:07:19'),
(34, 'کوئی شک', 'doubt', 'شک نشته', '', 1, '2025-08-24 09:07:19'),
(35, 'جس میں', 'in it', 'په کوم کې', '', 1, '2025-08-24 09:07:19'),
(36, 'ہدایت ہے', 'a Guidance', 'لارښوونه شته', '', 1, '2025-08-24 09:07:19'),
(37, 'واسطے ان کے جو متقی ہیں', 'for the God-conscious', 'د متقیانو لپاره', '', 1, '2025-08-24 09:07:19'),
(38, 'یہ وہ لوگ ہیں', 'Those who', 'دا خلک دي', '', 1, '2025-08-24 09:07:19'),
(39, 'جو ایمان لاتے ہیں', 'believe', 'هغه کسان چې ایمان لري', '', 1, '2025-08-24 09:07:19'),
(40, 'غیب پر', 'in the unseen', 'په غیب کې', '', 1, '2025-08-24 09:07:19'),
(41, 'اور وہ قائم کرتے ہیں', 'and establish', 'او دوی تاسیس کوي', '', 1, '2025-08-24 09:07:19'),
(42, 'نماز', 'the prayer', 'دعا', '', 1, '2025-08-24 09:07:19'),
(43, 'اس میں سے جو', 'and out of what', 'له هغه څه چې', '', 1, '2025-08-24 09:07:19'),
(44, 'رزق دیا ہم نے ان کو', 'We have provided them', 'موږ دوی ته روزي ورکړه', '', 1, '2025-08-24 09:07:19'),
(45, 'وہ خرچ کرتے ہیں', 'they spend', 'دوی مصرفوي', '', 1, '2025-08-24 09:07:19'),
(46, 'اور وہ لوگ', 'And those who', 'او هغه خلک', '', 1, '2025-08-24 09:07:19'),
(47, 'جو ایمان لاتے ہیں', 'believe', 'هغه کسان چې ایمان لري', '', 1, '2025-08-24 09:07:19'),
(48, 'ساتھ اس کے جو', 'in what', 'د هغه سره', '', 1, '2025-08-24 09:07:19'),
(49, 'نازل کیا گیا', '(is) sent down', 'څرګنده شوه', '', 1, '2025-08-24 09:07:19'),
(50, 'طرف اپ کے', 'to you', 'ستا په لور', '', 1, '2025-08-24 09:07:19'),
(51, 'اور جو', 'and what', 'او څه', '', 1, '2025-08-24 09:07:19'),
(52, 'نازل کیا گیا', 'was sent down', 'څرګنده شوه', '', 1, '2025-08-24 09:07:19'),
(53, 'سے', 'from', 'څخه', '', 1, '2025-08-24 09:07:19'),
(54, 'اپ سے پہلے', 'before you', 'ستاسو په وړاندې', '', 1, '2025-08-24 09:07:19'),
(55, 'اور اخرت کے ساتھ', 'and in the Hereafter', 'او د آخرت سره', '', 1, '2025-08-24 09:07:19'),
(56, 'وہ', 'they', 'هغه', '', 1, '2025-08-24 09:07:19'),
(57, 'وہ یقین رکھتے ہیں', 'firmly believe', 'دوی باور لري', '', 1, '2025-08-24 09:07:19'),
(58, 'یہی لوگ', 'Those', 'دا خلک دي', '', 1, '2025-08-24 09:07:19'),
(59, 'اوپر', '(are) on', 'پورته', '', 1, '2025-08-24 09:07:19'),
(60, 'ہدایت کے ہیں', 'Guidance', 'د لارښوونې وړ دي', '', 1, '2025-08-24 09:07:19'),
(61, 'سے', 'from', 'څخه', '', 1, '2025-08-24 09:07:19'),
(62, 'اپنے رب کی طرف سے', 'their Lord', 'له خپل رب څخه', '', 1, '2025-08-24 09:07:19'),
(63, 'اور یہی لوگ ہیں', 'and those', 'او دا خلک دي', '', 1, '2025-08-24 09:07:19'),
(64, 'وہ', 'they', 'هغه', '', 1, '2025-08-24 09:07:19'),
(65, 'جو فلاح پانے والے ہیں', '(are) the successful ones', 'هغه څوک چې برکت لري', '', 1, '2025-08-24 09:07:19'),
(66, 'بیشک', 'Indeed', 'البته', '', 1, '2025-08-24 09:07:19'),
(67, 'وہ لوگ', 'those who', 'هغه خلک', '', 1, '2025-08-24 09:07:19'),
(68, 'جنہوں نے کفر کیا', 'disbelieve[d]', 'هغه کسان چې کافران شوي دي', '', 1, '2025-08-24 09:07:19'),
(69, 'برابر ہے', '(it) is same', 'برابر دی', '', 1, '2025-08-24 09:07:19'),
(70, 'اوپر ان کے', 'to them', 'د دوی پورته', '', 1, '2025-08-24 09:07:19'),
(71, 'تم ڈراؤ ان کو', 'whether you warn them', 'تاسو دوی ډاروي', '', 1, '2025-08-24 09:07:19'),
(72, 'یا', 'or', 'یا', '', 1, '2025-08-24 09:07:19'),
(73, 'نہ', 'not', 'نه', '', 1, '2025-08-24 09:07:19'),
(74, 'تم ڈراؤ انکو', 'you warn them', 'تاسو دوی ډاروي', '', 1, '2025-08-24 09:07:19'),
(75, 'نہیں', 'not', 'نه', '', 1, '2025-08-24 09:07:19'),
(76, 'وہ ایمان لائیں گے', 'they believe', 'دوی به باور وکړي', '', 1, '2025-08-24 09:07:19'),
(77, 'مہر لگادیں', 'Has set a seal', 'مهر یې کړئ', '', 1, '2025-08-24 09:07:19'),
(78, 'اللہ نے', 'Allah', 'الله تعالی لري', '', 1, '2025-08-24 09:07:19'),
(79, 'اوپر', 'on', 'پورته', '', 1, '2025-08-24 09:07:19'),
(80, 'ان کے دلوں کے', 'their hearts', 'د دوی د زړونو څخه', '', 1, '2025-08-24 09:07:19'),
(81, 'اور اوپر', 'and on', 'او پورته', '', 1, '2025-08-24 09:07:19'),
(82, 'ان کے کانوں کے', 'their hearing', 'د دوی غوږونه', '', 1, '2025-08-24 09:07:19'),
(83, 'اور اوپر', 'and on', 'او پورته', '', 1, '2025-08-24 09:07:19'),
